namespace Metano.Tests.Fixtures;

/// <summary>
/// NFR-002 of spec 011: a project that asks no runtime type question pays
/// nothing for runtime types. <c>Fixtures/NoRuntimeQuestions/</c> holds a
/// source with records, methods and a string enum (no collections, exceptions,
/// numeric enums or runtime questions) and its output, pinned from the build
/// before stage 011b. The current transpile must equal the pin byte for byte;
/// the pin is never regenerated by the current compiler. Three amendments:
/// #664 added each record's .NET text (<c>$printMembers</c> / <c>toString</c>
/// and their default-text formatter import, baseline FR-093); #573 gave its
/// relative specifiers the <c>.js</c> extension of spec 004 FR-011; #695 routes
/// <c>Math.Abs(int)</c> through <c>absInt32</c> (which throws for
/// <c>int.MinValue</c>). None is a runtime-type cost; nothing else changed.
/// </summary>
public class NoRuntimeQuestionsFixtureTests
{
    [Test]
    public async Task Transpile_EqualsTheOutputPinnedBeforeStage011b()
    {
        var actual = TranspileFixture();
        var pinned = ReadPinnedOutput();

        await Assert
            .That(actual.Keys.Order(StringComparer.Ordinal))
            .IsEquivalentTo(pinned.Keys.Order(StringComparer.Ordinal));

        foreach (var (fileName, content) in pinned)
            await Assert.That(actual[fileName]).IsEqualTo(content);
    }

    /// <summary>The fixture's transpiled files, keyed by their output path.</summary>
    internal static Dictionary<string, string> TranspileFixture() =>
        TranspileHelper.Transpile(File.ReadAllText(SourcePath()));

    private static Dictionary<string, string> ReadPinnedOutput()
    {
        var root = PinnedDirectory();

        return Directory
            .EnumerateFiles(root, "*.ts", SearchOption.AllDirectories)
            .ToDictionary(
                path => Path.GetRelativePath(root, path).Replace('\\', '/'),
                File.ReadAllText
            );
    }

    private static string FixtureDirectory() =>
        Path.Combine(
            TranspileHelper.RepositoryRoot(),
            "tests",
            "Metano.Tests",
            "Fixtures",
            "NoRuntimeQuestions"
        );

    private static string SourcePath() =>
        Path.Combine(FixtureDirectory(), "NoRuntimeQuestions.cs.txt");

    private static string PinnedDirectory() => Path.Combine(FixtureDirectory(), "Pinned");
}
